//! Vietnamese cross-check: chart-svc against the open-source Vietnamese tử vi tool
//! `lasotuvi` (fixture generated by `tools/fixtures/lasotuvi/generate.py`, 50 charts).
//!
//! The must-match facts (lunar date, year can chi, cục, Mệnh and Thân branch, the 14 major
//! stars, Tuần and Triệt) are asserted. Everything else (minor and adjective stars, the
//! rings, Tứ Hóa, brightness) differs by school; `report_school_differences` prints the diff
//! table, run with `--ignored --nocapture`.

use chart_svc::adapters::engine::IztroAdapter;
use chart_svc::application::birth::NormalizedBirth;
use chart_svc::application::service::{ChartRequest, ChartService};
use chart_svc::domain::calendar::{Branch, CalendarKind};
use chart_svc::domain::chart::{Chart, Gender, Palace, PalaceKey};
use serde_json::Value;
use std::collections::{BTreeMap, BTreeSet};
use time::macros::format_description;
use time::Date;

const FIXTURE: &str = include_str!("fixtures/lasotuvi.json");

fn fixture() -> Vec<Value> {
    let v: Value = serde_json::from_str(FIXTURE).expect("fixture parses");
    v["cases"].as_array().expect("cases").clone()
}

fn s(v: &Value) -> &str {
    v.as_str().expect("string")
}

fn chart_of(case: &Value) -> Chart {
    let solar = Date::parse(
        s(&case["solar"]),
        format_description!("[year]-[month]-[day]"),
    )
    .expect("date");
    let hour = Branch::ALL[usize::try_from(case["hourBranch"].as_u64().unwrap()).unwrap()];
    let gender = match s(&case["gender"]) {
        "male" => Gender::Male,
        "female" => Gender::Female,
        other => panic!("gender {other}"),
    };
    let req = ChartRequest {
        birth: NormalizedBirth::from_parts(solar, hour, CalendarKind::Vn),
        gender,
    };
    ChartService::new(IztroAdapter)
        .chart(&req)
        .expect("chart-svc casts the chart")
}

fn palace_with(chart: &Chart, key: PalaceKey) -> &Palace {
    chart
        .palaces
        .iter()
        .find(|p| p.key == key)
        .expect("palace exists")
}

fn pair(v: &Value) -> BTreeSet<String> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|b| s(b).to_string())
        .collect()
}

fn pair_of(branches: [Branch; 2]) -> BTreeSet<String> {
    branches.iter().map(|b| b.key().to_string()).collect()
}

/// Facts that must be equal. Each difference is `case: field: ours != lasotuvi`.
fn must_match(case: &Value, out: &mut Vec<String>) {
    let id = s(&case["id"]);
    let chart = chart_of(case);
    let mut check = |field: &str, ours: String, theirs: String| {
        if ours != theirs {
            out.push(format!("{id}: {field}: {ours} != {theirs}"));
        }
    };
    let l = &case["lunar"];
    check(
        "lunar",
        format!(
            "{}-{}-{}{}",
            chart.lunar.year,
            chart.lunar.month,
            chart.lunar.day,
            if chart.lunar.leap { " leap" } else { "" }
        ),
        format!(
            "{}-{}-{}{}",
            l[0],
            l[1],
            l[2],
            if l[3].as_bool().unwrap() { " leap" } else { "" }
        ),
    );
    check(
        "year can chi",
        format!("{} {}", chart.year.stem.key(), chart.year.branch.key()),
        format!(
            "{} {}",
            s(&case["yearCanChi"][0]),
            s(&case["yearCanChi"][1])
        ),
    );
    check(
        "cuc",
        format!("{} {}", chart.cuc.name_vi(), chart.cuc.number),
        format!("{} {}", s(&case["cuc"]["name"]), case["cuc"]["number"]),
    );
    check(
        "menh",
        palace_with(&chart, PalaceKey::Menh).branch.key().into(),
        s(&case["menh"]).into(),
    );
    check(
        "than",
        palace_with(&chart, chart.than_palace).branch.key().into(),
        s(&case["than"]).into(),
    );
    let mut ours: BTreeMap<&str, &str> = BTreeMap::new();
    for p in &chart.palaces {
        for st in &p.major {
            ours.insert(st.key.key(), p.branch.key());
        }
    }
    let theirs = case["major"].as_object().unwrap();
    check(
        "major star count",
        ours.len().to_string(),
        theirs.len().to_string(),
    );
    for (star, branch) in theirs {
        check(
            &format!("major {star}"),
            ours.get(star.as_str()).copied().unwrap_or("-").into(),
            s(branch).into(),
        );
    }
    let mut set_check = |field: &str, o: BTreeSet<String>, t: BTreeSet<String>| {
        if o != t {
            out.push(format!("{id}: {field}: {o:?} != {t:?}"));
        }
    };
    set_check("tuan", pair_of(chart.tuan), pair(&case["tuan"]));
    set_check("triet", pair_of(chart.triet), pair(&case["triet"]));
}

#[test]
fn fixture_has_fifty_cases_covering_every_hour_and_both_genders() {
    let cases = fixture();
    assert_eq!(cases.len(), 50);
    let hours: BTreeSet<u64> = cases
        .iter()
        .map(|c| c["hourBranch"].as_u64().unwrap())
        .collect();
    assert_eq!(hours.len(), 12, "all 12 hour branches");
    for g in ["male", "female"] {
        assert!(cases.iter().any(|c| s(&c["gender"]) == g), "{g} present");
    }
    for date in ["1985-01-21", "1968-01-29", "2007-02-17", "2023-04-01"] {
        assert!(cases.iter().any(|c| s(&c["solar"]) == date), "{date}");
    }
}

#[test]
fn must_match_facts_equal_lasotuvi() {
    let cases = fixture();
    let mut out = Vec::new();
    for c in &cases {
        must_match(c, &mut out);
    }
    assert!(
        out.is_empty(),
        "{} must-match differences in {} cases:\n{}",
        out.len(),
        cases.len(),
        out.join("\n")
    );
}

/// Star placements per group as `key -> branches` for one chart.
fn ours_by_group(chart: &Chart) -> BTreeMap<&'static str, BTreeMap<String, BTreeSet<String>>> {
    let mut g: BTreeMap<&'static str, BTreeMap<String, BTreeSet<String>>> = BTreeMap::new();
    let mut put_value = |group: &'static str, key: &str, value: &str| {
        g.entry(group)
            .or_default()
            .entry(key.to_string())
            .or_default()
            .insert(value.to_string());
    };
    for p in &chart.palaces {
        for st in &p.minor {
            put_value("minor", st.key.key(), p.branch.key());
        }
        for st in p.major.iter().chain(&p.minor) {
            if let Some(b) = st.brightness {
                put_value("brightness", st.key.key(), b.key());
            }
            if let Some(m) = st.mutagen {
                put_value("mutagen", m.key(), p.branch.key());
            }
        }
        for a in &p.adjective {
            put_value("adjective", a.key(), p.branch.key());
        }
        put_value("changsheng", p.changsheng.key(), p.branch.key());
        put_value("boshi", p.boshi.key(), p.branch.key());
        put_value("suiqian", p.suiqian.key(), p.branch.key());
    }
    g
}

/// lasotuvi's placements in the same shape (`brightness` values are levels, not branches).
fn theirs_by_group(case: &Value) -> BTreeMap<&'static str, BTreeMap<String, BTreeSet<String>>> {
    let mut g: BTreeMap<&'static str, BTreeMap<String, BTreeSet<String>>> = BTreeMap::new();
    for group in [
        "minor",
        "adjective",
        "changsheng",
        "boshi",
        "suiqian",
        "mutagen",
    ] {
        for (star, v) in case[group].as_object().unwrap() {
            let branches: BTreeSet<String> = match v {
                Value::String(b) => BTreeSet::from([b.clone()]),
                other => pair(other),
            };
            g.entry(group).or_default().insert(star.clone(), branches);
        }
    }
    for (star, level) in case["brightness"].as_object().unwrap() {
        g.entry("brightness")
            .or_default()
            .insert(star.clone(), BTreeSet::from([s(level).to_string()]));
    }
    g
}

/// One row of the school-difference table.
#[derive(Default)]
struct Differing {
    cases: usize,
    example: String,
    by_stem: BTreeMap<String, usize>,
    by_polarity: BTreeMap<&'static str, usize>,
}

/// Prints the school-difference table: per group and star, in how many of the cases the
/// placement differs, with the first differing case. Ignored by default (it is the data for
/// `docs/tuvi/vn-school-diff.md`, not an assertion).
#[test]
#[ignore = "report only: cargo test --test vn_crosscheck -- --ignored --nocapture"]
fn report_school_differences() {
    let cases = fixture();
    // group -> star -> (cases differing, first example, differing cases by year stem and by
    // polarity: year yin/yang times gender, + when a yang-year man or yin-year woman)
    let mut table: BTreeMap<&str, BTreeMap<String, Differing>> = BTreeMap::new();
    for c in &cases {
        let ours = ours_by_group(&chart_of(c));
        let theirs = theirs_by_group(c);
        for (group, stars) in &theirs {
            let ours_group = ours.get(group).cloned().unwrap_or_default();
            for (star, want) in stars {
                let got = ours_group.get(star).cloned().unwrap_or_default();
                if got != *want {
                    let e = table
                        .entry(group)
                        .or_default()
                        .entry(star.clone())
                        .or_default();
                    e.cases += 1;
                    if e.example.is_empty() {
                        e.example = format!("{}: ours {got:?} lasotuvi {want:?}", s(&c["id"]));
                    }
                    *e.by_stem
                        .entry(s(&c["yearCanChi"][0]).to_string())
                        .or_default() += 1;
                    let yang_year = Branch::ALL
                        .iter()
                        .position(|b| b.key() == s(&c["yearCanChi"][1]))
                        .is_some_and(|i| i % 2 == 0);
                    let polarity = if yang_year == (s(&c["gender"]) == "male") {
                        "+"
                    } else {
                        "-"
                    };
                    *e.by_polarity.entry(polarity).or_default() += 1;
                }
            }
        }
    }
    println!(
        "group | star | cases differing of {} | by year stem | by polarity | first example",
        cases.len()
    );
    for (group, stars) in &table {
        for (star, d) in stars {
            println!(
                "{group} | {star} | {} | {:?} | {:?} | {}",
                d.cases, d.by_stem, d.by_polarity, d.example
            );
        }
    }
}
